  addEventListener('beforeinstallprompt',e=>{e.preventDefault();PWA.deferred=e;btn.hidden=false});
  addEventListener('appinstalled',()=>{PWA.deferred=null;btn.hidden=true;pwaHideBanner();toast('הארון הותקן')});

